  app.tickflow.summary.public \
  "Public URL" \
  "公网访问" \
  app.tickflow.summary.internal \
  "Internal URL" \
  "内网直连" \
  app.tickflow.summary.repo \
  "Repository" \
  "源码仓库" \
  app.tickflow.summary.compose \
  "Compose dir" \
  "Compose 目录" \
  app.tickflow.summary.data \
  "Data dir" \
  "数据目录" \
